import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  counters: defineTable({
    runId: v.string(),
    count: v.number(),
  }).index("by_runId", ["runId"]),
});

import { query, mutation } from "./_generated/server";
import { v } from "convex/values";

export const get = query({
  args: { runId: v.string() },
  handler: async (ctx, args) => {
    const counter = await ctx.db
      .query("counters")
      .withIndex("by_runId", (q) => q.eq("runId", args.runId))
      .first();
    return counter;
  },
});

export const increment = mutation({
  args: { runId: v.string() },
  handler: async (ctx, args) => {
    const counter = await ctx.db
      .query("counters")
      .withIndex("by_runId", (q) => q.eq("runId", args.runId))
      .first();
    if (counter) {
      await ctx.db.patch(counter._id, { count: counter.count + 1 });
      return counter.count + 1;
    } else {
      const id = await ctx.db.insert("counters", {
        runId: args.runId,
        count: 1,
      });
      return 1;
    }
  },
});

import { useQuery, useMutation } from 'convex/react'
import { api } from '../convex/_generated/api'
import './App.css'

function App() {
  const runId = import.meta.env.VITE_RUN_ID;
  const counter = useQuery(api.counters.get, { runId });
  const increment = useMutation(api.counters.increment);

  return (
    <>
      <section id="center">
        <div>
          <h1>Collaborative Counter</h1>
          <p>Run ID: {runId}</p>
        </div>
        <button
          type="button"
          className="counter"
          onClick={() => increment({ runId })}
          disabled={counter === undefined}
        >
          Increment
        </button>
        <p>Count: {counter === undefined ? '...' : counter.count}</p>
      </section>
    </>
  )
}

export default App

